"""Weyl algebras (new in 2.0): the Rational, Fp3 and Nimber backend families.

Each family has the same four classes -- ``*WeylAlgebra``, ``*WeylElement``,
``*SparsePolynomial``, ``*WeylPSymbol`` -- and the same contract:

* PBW products with ``[d, x] = 1`` and independent checked budgets,
* automorphisms checked against substitution on the generators,
* in positive characteristic, the centre generated by ``z_i^p``, central
  fibres, ``p``-symbols and split modules,
* in characteristic two, the independent Clifford-fibre oracle,
* monomorphism: elements of different contexts raise ``ValueError``, elements
  of different backends raise ``TypeError``.

Laws are asserted against independent oracles (substitution into generators,
matrix arithmetic in Python, brute-force module action) wherever one exists.
"""

import itertools
import random
import unittest

import ogdoad as og

from _support import OgdoadTestCase


# ---------------------------------------------------------------------------
# Family descriptors
# ---------------------------------------------------------------------------


class Family:
    def __init__(self, name, scalar, alg, elem, poly, psym, char, rand):
        self.name = name
        self.Scalar = scalar
        self.Alg = alg
        self.Elem = elem
        self.Poly = poly
        self.PSym = psym
        self.char = char
        self.rand = rand  # rng -> scalar

    def sc(self, value):
        """Scalar for a small non-negative integer (nimbers are unsigned)."""
        return self.Scalar(value)


RATIONAL = Family(
    "Rational", og.Rational, og.RationalWeylAlgebra, og.RationalWeylElement,
    og.RationalSparsePolynomial, og.RationalWeylPSymbol, 0,
    lambda rng: og.Rational(rng.randint(-3, 3), rng.randint(1, 3)))
FP3 = Family(
    "Fp3", og.Fp3, og.Fp3WeylAlgebra, og.Fp3WeylElement,
    og.Fp3SparsePolynomial, og.Fp3WeylPSymbol, 3,
    lambda rng: og.Fp3(rng.randint(0, 2)))
NIMBER = Family(
    "Nimber", og.Nimber, og.NimberWeylAlgebra, og.NimberWeylElement,
    og.NimberSparsePolynomial, og.NimberWeylPSymbol, 2,
    lambda rng: og.Nimber(rng.randint(0, 7)))
FAMILIES = (RATIONAL, FP3, NIMBER)


def rand_element(W, fam, rng, terms=4, max_exp=3):
    total = W.zero()
    for _ in range(terms):
        exps = [rng.randrange(max_exp) for _ in range(W.dim())]
        total = total + W.monomial(exps, fam.rand(rng))
    return total


def substitute(W, element, images):
    """Evaluate a PBW polynomial on ``images`` (one element per generator).

    This is the independent oracle for an algebra homomorphism: it is
    determined by the images of the generators.
    """
    total = W.zero()
    for exps, coeff in element.terms():
        term = W.scalar(coeff)
        for image, e in zip(images, exps):
            term = term * W.pow(image, e)
        total = total + term
    return total


def matmul(fam, a, b):
    n = len(a)
    zero = fam.sc(0)
    return [[sum((a[i][k] * b[k][j] for k in range(n)), zero) for j in range(n)]
            for i in range(n)]


def matadd(a, b):
    return [[x + y for x, y in zip(r, s)] for r, s in zip(a, b)]


def matsub(a, b):
    return [[x - y for x, y in zip(r, s)] for r, s in zip(a, b)]


def identity(fam, n):
    return [[fam.sc(1 if i == j else 0) for j in range(n)] for i in range(n)]


def scalar_matrix(fam, n, value):
    return [[value if i == j else fam.sc(0) for j in range(n)] for i in range(n)]


def matpow(fam, m, e):
    out = identity(fam, len(m))
    for _ in range(e):
        out = matmul(fam, out, m)
    return out


# ---------------------------------------------------------------------------
# Laws common to all three backends
# ---------------------------------------------------------------------------


class WeylFamilyLaws:
    """Mixin run once per backend; ``fam`` selects the descriptor."""

    fam = None

    # -- construction and rendering ------------------------------------

    def test_standard_context(self):
        fam = self.fam
        W = fam.Alg(2)
        self.assertEqual((W.dim(), W.standard_pairs()), (4, 2))
        self.assertEqual(repr(W), f"{fam.Alg.__name__}(standard_pairs=2)")
        form = W.commutator_form()
        one, zero = fam.sc(1), fam.sc(0)
        for i, j in itertools.product(range(4), repeat=2):
            if (i, j) in ((0, 2), (1, 3)):
                self.assertEqual(form[i][j], -one)  # [z_i, z_{n+i}] = -1
            elif (i, j) in ((2, 0), (3, 1)):
                self.assertEqual(form[i][j], one)
            else:
                self.assertEqual(form[i][j], zero)
        # Generators are ordered positions first, then momenta.
        self.assertEqual([W.generator(i) for i in range(4)],
                         [W.x(0), W.x(1), W.d(0), W.d(1)])

    def test_rank_zero_algebra(self):
        W = self.fam.Alg(0)
        self.assertEqual((W.dim(), W.standard_pairs()), (0, 0))
        self.assertEqual(W.one() * W.one(), W.one())
        self.assertNotEqual(W.one(), W.zero())
        with self.assertRaises(ValueError):
            W.x(0)

    def test_element_reprs(self):
        fam = self.fam
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        self.assertEqual(repr(x), "z0")
        self.assertEqual(str(d), "z1")
        self.assertEqual(repr(x * d), "z0⋅z1")
        self.assertEqual(repr(x ** 3), "z0↑3")
        self.assertEqual(repr(x + d), "z1 + z0")
        one = repr(fam.sc(1))
        self.assertEqual(repr(W.one()), one)
        self.assertEqual(repr(W.zero()), repr(fam.sc(0)) if fam.char == 2 else "0")

    # -- the PBW normal form and the canonical commutator ---------------

    def test_commutator_of_d_and_x_is_one(self):
        fam = self.fam
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        self.assertEqual(W.commutator(d, x), W.one())
        self.assertEqual(W.commutator(x, d), -W.one())
        self.assertEqual(d * x, x * d + W.one())
        self.assertEqual(d * x - x * d, W.one())
        self.assertEqual(x.algebra().commutator(d, x), W.one())

    def test_pbw_normal_form_puts_positions_before_momenta(self):
        fam = self.fam
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        self.assertEqual((x * d).terms(), [([1, 1], fam.sc(1))])
        self.assertEqual((d * x).terms(), [([0, 0], fam.sc(1)), ([1, 1], fam.sc(1))])
        self.assertEqual((d * x).term_count(), 2)
        self.assertEqual(W.monomial([2, 1], fam.sc(1)).terms(), [([2, 1], fam.sc(1))])
        # d^2 x = x d^2 + 2 d   (the 2 is 1 + 1, which vanishes in characteristic two)
        two = fam.sc(1) + fam.sc(1)
        lhs = (d * d) * x
        rhs = x * (d * d) + d.scale(two)
        self.assertEqual(lhs, rhs)

    def test_weyl_relations_in_rank_two(self):
        fam = self.fam
        W = fam.Alg(2)
        zero, one = W.zero(), W.one()
        for i, j in itertools.product(range(2), repeat=2):
            self.assertEqual(W.commutator(W.d(i), W.x(j)), one if i == j else zero)
            self.assertEqual(W.commutator(W.x(i), W.x(j)), zero)
            self.assertEqual(W.commutator(W.d(i), W.d(j)), zero)

    def test_commutators_of_generators_follow_the_commutator_form(self):
        fam = self.fam
        for W in (fam.Alg(2), fam.Alg(1).direct_sum(fam.Alg(1))):
            form = W.commutator_form()
            for i, j in itertools.product(range(W.dim()), repeat=2):
                self.assertEqual(W.commutator(W.generator(i), W.generator(j)),
                                 W.scalar(form[i][j]))

    # -- ring laws ------------------------------------------------------

    def test_ring_axioms_rank_one(self):
        fam = self.fam
        W = fam.Alg(1)
        rng = random.Random(100 + fam.char)
        pool = [rand_element(W, fam, rng, terms=3) for _ in range(5)]
        pool += [W.zero(), W.one(), W.x(0), W.d(0)]
        zero, one = W.zero(), W.one()
        for a in pool:
            self.assertEqual(a + zero, a)
            self.assertEqual(a - a, zero)
            self.assertEqual(a + (-a), zero)
            self.assertEqual(a * one, a)
            self.assertEqual(one * a, a)
            self.assertEqual(a * zero, zero)
        for a, b in itertools.product(pool, repeat=2):
            self.assertEqual(a + b, b + a)
            self.assertEqual(W.mul(a, b), a * b)
            self.assertEqual(a.mul(b), a * b)
        for a, b, c in itertools.product(pool, repeat=3):
            self.assertEqual((a * b) * c, a * (b * c))
            self.assertEqual(a * (b + c), a * b + a * c)
            self.assertEqual((a + b) * c, a * c + b * c)

    def test_ring_axioms_rank_two(self):
        fam = self.fam
        W = fam.Alg(2)
        rng = random.Random(200 + fam.char)
        pool = [rand_element(W, fam, rng, terms=3, max_exp=2) for _ in range(4)]
        for a, b, c in itertools.product(pool, repeat=3):
            self.assertEqual((a * b) * c, a * (b * c))
            self.assertEqual(a * (b + c), a * b + a * c)

    def test_powers(self):
        fam = self.fam
        W = fam.Alg(1)
        a = W.x(0) + W.d(0)
        self.assertEqual(a ** 0, W.one())
        self.assertEqual(a ** 1, a)
        self.assertEqual(a ** 4, a * a * a * a)
        self.assertEqual(W.pow(a, 3), a ** 3)
        self.assertEqual(a.pow(3), a ** 3)
        self.assertEqual(a ** 5, (a ** 2) * (a ** 3))
        with self.assertRaises(ValueError):
            pow(a, 2, 5)  # modular exponentiation is not defined

    def test_lie_algebra_structure(self):
        fam = self.fam
        W = fam.Alg(2)
        rng = random.Random(300 + fam.char)
        pool = [rand_element(W, fam, rng, terms=2, max_exp=2) for _ in range(4)]
        for a, b in itertools.product(pool, repeat=2):
            self.assertEqual(W.commutator(a, b), -W.commutator(b, a))
            self.assertEqual(W.commutator(a, b), a * b - b * a)
        for a, b, c in itertools.product(pool, repeat=3):
            # Jacobi
            jac = (W.commutator(a, W.commutator(b, c)) + W.commutator(b, W.commutator(c, a))
                   + W.commutator(c, W.commutator(a, b)))
            self.assertTrue(jac.is_zero())
            # [a, bc] = [a, b] c + b [a, c]
            self.assertEqual(W.commutator(a, b * c),
                             W.commutator(a, b) * c + b * W.commutator(a, c))

    def test_scalars_embed_centrally(self):
        fam = self.fam
        W = fam.Alg(1)
        s = fam.sc(2)
        x = W.x(0)
        self.assertEqual(W.scalar(s) * x, x.scale(s))
        self.assertEqual(x * W.scalar(s), x.scale(s))
        self.assertTrue(W.is_central(W.scalar(s)))
        self.assertEqual(W.scalar(fam.sc(0)), W.zero())
        self.assertEqual(W.scalar(fam.sc(1)), W.one())
        # Small integers coerce into the scalar world; other worlds do not.
        self.assertEqual(W.scalar(2), W.scalar(s))
        self.assertEqual(x.scale(2), x.scale(s))

    def test_zero_has_a_canonical_empty_normal_form(self):
        fam = self.fam
        W = fam.Alg(1)
        x = W.x(0)
        for zero in (x - x, W.monomial([1, 0], fam.sc(0)), W.zero(), x.scale(fam.sc(0)),
                     W.scalar(fam.sc(0)), W.mul(W.zero(), x)):
            self.assertEqual(zero.terms(), [])
            self.assertEqual(zero.term_count(), 0)
            self.assertTrue(zero.is_zero())
            self.assertEqual(zero, W.zero())
        self.assertTrue(W.principal_symbol(W.zero(), "bernstein").is_zero())
        self.assertEqual(W.zero() ** 0, W.one())  # the empty product

    def test_polynomial_arguments_must_have_the_matching_dimension(self):
        fam = self.fam
        W = fam.Alg(1)
        P = fam.Poly
        with self.assertRaises(ValueError):
            W.act_on_sparse_polynomial(W.x(0), P.monomial([1, 2], fam.sc(1)))  # needs n = 1 variable
        with self.assertRaises(ValueError):
            W.poisson_bracket(P.variable(3, 0), P.variable(3, 1))  # needs 2n = 2 variables
        with self.assertRaises(ValueError):
            W.poisson_bracket(P.variable(1, 0), P.variable(1, 0))
        self.assertNotEqual(P(1), P(2))

    def test_element_equality_is_structural_across_equal_contexts(self):
        fam = self.fam
        W1, W2 = fam.Alg(1), fam.Alg(1)
        a, b = W1.x(0), W2.x(0)
        self.assertEqual(a, b)
        self.assertEqual(a + b, a + a)
        self.assertEqual(a * W2.d(0), W1.x(0) * W1.d(0))
        self.assertEqual(a.algebra().dim(), 2)
        self.assertNotEqual(a, W1.d(0))
        self.assertFalse(a == None)  # noqa: E711
        self.assertFalse(a == 1)

    # -- degrees, symbols, brackets ------------------------------------

    def test_degrees_and_principal_symbols(self):
        fam = self.fam
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        self.assertEqual((W.bernstein_degree(d * x), W.differential_order(d * x)), (2, 1))
        self.assertEqual((W.bernstein_degree(x ** 3), W.differential_order(x ** 3)), (3, 0))
        self.assertIsNone(W.bernstein_degree(W.zero()))
        self.assertIsNone(W.differential_order(W.zero()))
        self.assertEqual(W.bernstein_degree(W.one()), 0)
        t0t1 = fam.Poly.monomial([1, 1], fam.sc(1))
        self.assertEqual(W.principal_symbol(d * x, "bernstein"), t0t1)
        self.assertEqual(W.principal_symbol(d * x, "differential_order"), t0t1)
        self.assertEqual(W.principal_symbol(d * x, "differential"), t0t1)
        with self.assertRaises(ValueError):
            W.principal_symbol(d * x, "growth")

    def test_filtration_degree_is_additive_and_the_symbol_multiplicative(self):
        fam = self.fam
        W = fam.Alg(1)
        rng = random.Random(400 + fam.char)
        for _ in range(12):
            a, b = rand_element(W, fam, rng, 2), rand_element(W, fam, rng, 2)
            if a.is_zero() or b.is_zero():
                continue
            ab = a * b
            if ab.is_zero():
                continue  # zero divisors cannot occur here, but stay defensive
            for name, degree in (("bernstein", W.bernstein_degree),
                                 ("differential_order", W.differential_order)):
                self.assertEqual(degree(ab), degree(a) + degree(b))
                self.assertEqual(W.principal_symbol(ab, name),
                                 W.principal_symbol(a, name) * W.principal_symbol(b, name))

    def test_poisson_bracket(self):
        fam = self.fam
        W = fam.Alg(1)
        P = fam.Poly
        t0, t1 = P.variable(2, 0), P.variable(2, 1)
        one = P.scalar(2, fam.sc(1))
        self.assertEqual(W.poisson_bracket(t1, t0), one)
        self.assertEqual(W.poisson_bracket(t0, t1), -one)
        self.assertTrue(W.poisson_bracket(t0, t0).is_zero())
        rng = random.Random(500 + fam.char)
        polys = [P.monomial([rng.randrange(3), rng.randrange(3)], fam.rand(rng))
                 + P.monomial([rng.randrange(3), rng.randrange(3)], fam.rand(rng))
                 for _ in range(4)]
        for f, g, h in itertools.product(polys, repeat=3):
            self.assertEqual(W.poisson_bracket(f, g), -W.poisson_bracket(g, f))
            # Leibniz: {f, g h} = {f, g} h + g {f, h}
            self.assertEqual(W.poisson_bracket(f, g * h),
                             W.poisson_bracket(f, g) * h + g * W.poisson_bracket(f, h))

    def test_hbar_deformation(self):
        fam = self.fam
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        zero, one = fam.sc(0), fam.sc(1)
        self.assertEqual(W.hbar_commutator(d, x, zero), W.zero())
        self.assertEqual(W.hbar_commutator(d, x, one), W.one())
        for h in (fam.sc(2), fam.sc(1)):
            self.assertEqual(W.hbar_commutator(d, x, h), W.scalar(h))  # [d, x]_h = h
        self.assertEqual(W.hbar_product(d, x, one), d * x)
        self.assertEqual(W.hbar_product(x, d, one), x * d)
        # At hbar = 0 the algebra is commutative.
        rng = random.Random(600 + fam.char)
        for _ in range(6):
            a, b = rand_element(W, fam, rng, 2), rand_element(W, fam, rng, 2)
            self.assertEqual(W.hbar_product(a, b, zero), W.hbar_product(b, a, zero))
            self.assertEqual(W.hbar_product(a, b, one), a * b)
            self.assertTrue(W.hbar_commutator(a, b, zero).is_zero())

    def test_hbar_product_is_the_standard_product_conjugated_by_d_to_hbar_d(self):
        # In [d, x] = hbar the map x -> x, d -> hbar d identifies the deformed
        # algebra with the standard one when hbar is invertible, so
        #   a *_hbar b = psi^{-1}(psi(a) psi(b)),  psi(x^i d^j) = hbar^j x^i d^j.
        fam = self.fam
        for n in (1, 2):
            W = fam.Alg(n)
            h = fam.sc(2)
            h_inv = h.inv()

            def psi(element, factor):
                total = W.zero()
                for exps, coeff in element.terms():
                    weight = fam.sc(1)
                    for _ in range(sum(exps[n:]) % 64):
                        weight = weight * factor
                    total = total + W.monomial(exps, coeff * weight)
                return total

            rng = random.Random(3500 + fam.char + n)
            for _ in range(4):
                a = rand_element(W, fam, rng, 3, max_exp=3)
                b = rand_element(W, fam, rng, 3, max_exp=3)
                expected = psi(psi(a, h) * psi(b, h), h_inv)
                self.assertEqual(W.hbar_product(a, b, h), expected)
                self.assertEqual(W.hbar_commutator(a, b, h),
                                 W.hbar_product(a, b, h) - W.hbar_product(b, a, h))

    def test_commutators_with_powers_are_derivatives(self):
        # [d, x^k] = k x^(k-1) and [d^k, x] = k d^(k-1); k is the k-fold sum of 1.
        fam = self.fam
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        one = fam.sc(1)
        for k in range(1, 8):
            k_elt = fam.sc(0)
            for _ in range(k):
                k_elt = k_elt + one
            self.assertEqual(W.commutator(d, x ** k), (x ** (k - 1)).scale(k_elt), k)
            self.assertEqual(W.commutator(d ** k, x), (d ** (k - 1)).scale(k_elt), k)

    def test_module_action_on_sparse_polynomials(self):
        fam = self.fam
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        P = fam.Poly
        # d acts as the formal derivative, x as multiplication by t.
        for k in range(6):
            tk = P.monomial([k], fam.sc(1))
            self.assertEqual(W.act_on_sparse_polynomial(x, tk), P.monomial([k + 1], fam.sc(1)))
            expected = tk.partial_derivative(0)
            self.assertEqual(W.act_on_sparse_polynomial(d, tk), expected)
        # It is a left module: (ab).p = a.(b.p), and [d, x] acts as the identity.
        rng = random.Random(700 + fam.char)
        for _ in range(8):
            a, b = rand_element(W, fam, rng, 2), rand_element(W, fam, rng, 2)
            p = P.monomial([rng.randrange(5)], fam.rand(rng)) + P.monomial([rng.randrange(5)], fam.rand(rng))
            self.assertEqual(W.act_on_sparse_polynomial(a * b, p),
                             W.act_on_sparse_polynomial(a, W.act_on_sparse_polynomial(b, p)))
            self.assertEqual(W.act_on_sparse_polynomial(W.commutator(d, x), p), p)

    def test_derivative_of_a_power_depends_on_the_characteristic(self):
        fam = self.fam
        W = fam.Alg(1)
        t3 = fam.Poly.monomial([3], fam.sc(1))
        derivative = W.act_on_sparse_polynomial(W.d(0), t3)
        if fam.char == 0:
            self.assertEqual(derivative, fam.Poly.monomial([2], fam.sc(3)))
        elif fam.char == 3:
            self.assertTrue(derivative.is_zero())  # d(t^3) = 3 t^2 = 0
        else:
            self.assertEqual(derivative, fam.Poly.monomial([2], fam.sc(1)))  # 3 = 1 mod 2

    # -- automorphisms --------------------------------------------------

    def automorphisms(self, W):
        """(name, callable on elements, images of x and d) in rank one."""
        fam = self.fam
        x, d = W.x(0), W.d(0)
        s = fam.sc(2)
        a = fam.sc(1)
        t = [fam.sc(1), fam.sc(2)]
        return [
            ("fourier", W.fourier, (d, -x)),
            ("parity", W.parity, (-x, -d)),
            ("scaling", lambda e: W.scaling(e, [s]), (x.scale(s), d.scale(s.inv()))),
            ("shear", lambda e: W.shear(e, [[a]]), (x, d + x.scale(a))),
            ("translation", lambda e: W.translation(e, t),
             (x + W.scalar(t[0]), d + W.scalar(t[1]))),
        ]

    def test_generator_images_of_the_standard_automorphisms(self):
        W = self.fam.Alg(1)
        x, d = W.x(0), W.d(0)
        for name, phi, (ix, id_) in self.automorphisms(W):
            with self.subTest(map=name):
                self.assertEqual(phi(x), ix)
                self.assertEqual(phi(d), id_)
                self.assertEqual(phi(W.one()), W.one())

    def test_automorphisms_agree_with_substitution_and_multiply(self):
        fam = self.fam
        W = fam.Alg(1)
        rng = random.Random(800 + fam.char)
        for name, phi, images in self.automorphisms(W):
            for _ in range(5):
                a, b = rand_element(W, fam, rng, 3), rand_element(W, fam, rng, 3)
                with self.subTest(map=name):
                    self.assertEqual(phi(a), substitute(W, a, images))  # independent oracle
                    self.assertEqual(phi(a * b), phi(a) * phi(b))
                    self.assertEqual(phi(a + b), phi(a) + phi(b))
                    self.assertEqual(phi(W.commutator(a, b)), W.commutator(phi(a), phi(b)))

    def test_fourier_has_order_four_and_an_inverse(self):
        fam = self.fam
        W = fam.Alg(1)
        rng = random.Random(900 + fam.char)
        for _ in range(6):
            a = rand_element(W, fam, rng, 3)
            self.assertEqual(W.fourier_inverse(W.fourier(a)), a)
            self.assertEqual(W.fourier(W.fourier_inverse(a)), a)
            f4 = a
            for _ in range(4):
                f4 = W.fourier(f4)
            self.assertEqual(f4, a)

    def test_formal_adjoint_is_an_involutive_anti_automorphism(self):
        fam = self.fam
        W = fam.Alg(1)
        rng = random.Random(1000 + fam.char)
        x, d = W.x(0), W.d(0)
        self.assertEqual(W.formal_adjoint(x), x)
        self.assertEqual(W.formal_adjoint(d), -d)
        for _ in range(6):
            a, b = rand_element(W, fam, rng, 3), rand_element(W, fam, rng, 3)
            self.assertEqual(W.formal_adjoint(a * b), W.formal_adjoint(b) * W.formal_adjoint(a))
            self.assertEqual(W.formal_adjoint(W.formal_adjoint(a)), a)

    def test_automorphisms_in_rank_two(self):
        fam = self.fam
        W = fam.Alg(2)
        rng = random.Random(1100 + fam.char)
        s = [fam.sc(2), fam.sc(1)]
        shear = [[fam.sc(1), fam.sc(2)], [fam.sc(2), fam.sc(0)]]  # symmetric
        t = [fam.sc(1), fam.sc(0), fam.sc(2), fam.sc(1)]
        maps = [lambda e: W.fourier(e), lambda e: W.scaling(e, s),
                lambda e: W.shear(e, shear), lambda e: W.translation(e, t)]
        for phi in maps:
            for _ in range(2):
                a, b = (rand_element(W, fam, rng, 2, max_exp=2) for _ in range(2))
                self.assertEqual(phi(a * b), phi(a) * phi(b))
        with self.assertRaises(ValueError):
            W.shear(W.x(0), [[fam.sc(1), fam.sc(2)], [fam.sc(0), fam.sc(0)]])  # not symmetric

    def test_affine_maps_between_contexts_are_homomorphisms(self):
        fam = self.fam
        W, W2 = fam.Alg(1), fam.Alg(2)
        x, d = W.x(0), W.d(0)
        one, zero = fam.sc(1), fam.sc(0)
        # x -> x0 + c, d -> d0 + e embeds W into W2 (columns: source generators).
        linear = [[one, zero], [zero, zero], [zero, one], [zero, zero]]
        shift = [fam.sc(2), fam.sc(1)]
        images = (W2.x(0) + W2.scalar(shift[0]), W2.d(0) + W2.scalar(shift[1]))
        rng = random.Random(1200 + fam.char)
        for _ in range(5):
            a, b = rand_element(W, fam, rng, 3), rand_element(W, fam, rng, 3)
            image = W.affine_map_to(W2, a, linear, shift)
            self.assertEqual(image, substitute(W2, a, images))
            self.assertEqual(image.algebra().dim(), 4)
            self.assertEqual(W.affine_map_to(W2, a * b, linear, shift),
                             W.affine_map_to(W2, a, linear, shift)
                             * W.affine_map_to(W2, b, linear, shift))
        # The identity map with a translation is ``translation``.
        ident = [[one, zero], [zero, one]]
        self.assertEqual(W.affine_map_to(W, d * x, ident, shift), W.translation(d * x, shift))

    def test_maps_that_break_the_commutator_are_refused(self):
        fam = self.fam
        W = fam.Alg(1)
        two = fam.sc(2)
        bad = [[two, fam.sc(0)], [fam.sc(0), fam.sc(1)]]  # [2x, d] = 2 != 1 unless 2 = 1
        if fam.char == 2:
            bad = [[fam.sc(0), fam.sc(0)], [fam.sc(0), fam.sc(1)]]  # kills x
        with self.assertRaises(ValueError):
            W.affine_map_to(W, W.x(0), bad, [fam.sc(0), fam.sc(0)])

    def test_direct_sum_is_a_block_presentation(self):
        fam = self.fam
        W = fam.Alg(1)
        D = W.direct_sum(W)
        self.assertEqual(D.dim(), 4)
        self.assertIsNone(D.standard_pairs())
        form = D.commutator_form()
        w_form = W.commutator_form()
        for i, j in itertools.product(range(4), repeat=2):
            expected = w_form[i % 2][j % 2] if i // 2 == j // 2 else fam.sc(0)
            self.assertEqual(form[i][j], expected)
        self.assertEqual(repr(D), f"{fam.Alg.__name__}(dim=4)")
        # Elements of the two blocks commute.
        a, b = D.generator(0), D.generator(2)
        self.assertTrue(D.commutator(a, b).is_zero())

    # -- budgets and checked boundaries ---------------------------------

    def test_budget_exhaustion_raises_value_error_and_is_monotone(self):
        fam = self.fam
        W = fam.Alg(1)
        a = W.x(0) + W.d(0)
        full = W.pow(a, 4)
        for key in ("max_terms", "max_steps"):
            needed = None
            for k in range(0, 3000):
                try:
                    result = W.pow(a, 4, **{key: k})
                except ValueError as exc:
                    self.assertIn("budget", str(exc))
                    continue
                needed = k
                self.assertEqual(result, full)
                break
            self.assertIsNotNone(needed, key)
            self.assertGreater(needed, 0)
            # Anything at or above the minimum still succeeds; just below fails.
            self.assertEqual(W.pow(a, 4, **{key: needed + 5}), full)
            with self.assertRaises(ValueError):
                W.pow(a, 4, **{key: needed - 1})
        # The sparse-term budget bounds the materialised result.
        terms_needed = min(k for k in range(100) if self._succeeds(lambda: W.pow(a, 4, max_terms=k)))
        self.assertGreaterEqual(terms_needed, full.term_count())

    @staticmethod
    def _succeeds(fn):
        try:
            fn()
        except ValueError:
            return False
        return True

    def test_every_budgeted_operation_reports_exhaustion(self):
        fam = self.fam
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        a = x + d
        s, one = fam.sc(2), fam.sc(1)
        P = fam.Poly
        poly = P.monomial([3], one) + P.monomial([1], one)
        shear = [[one]]
        calls = {
            "mul": lambda **k: W.mul(a, a, **k),
            "element.mul": lambda **k: a.mul(a, **k),
            "pow": lambda **k: W.pow(a, 3, **k),
            "element.pow": lambda **k: a.pow(3, **k),
            "commutator": lambda **k: W.commutator(x * d, a, **k),
            "act": lambda **k: W.act_on_sparse_polynomial(a * a, poly, **k),
            "poisson": lambda **k: W.poisson_bracket(
                P.variable(2, 0) * P.variable(2, 1), P.variable(2, 1), **k),
            "hbar_product": lambda **k: W.hbar_product(a, a, one, **k),
            "hbar_commutator": lambda **k: W.hbar_commutator(x * d, a, one, **k),
            "is_central": lambda **k: W.is_central(a * a, **k),
            "fourier": lambda **k: W.fourier(a * a, **k),
            "fourier_inverse": lambda **k: W.fourier_inverse(a * a, **k),
            "parity": lambda **k: W.parity(a * a, **k),
            "formal_adjoint": lambda **k: W.formal_adjoint(a * a, **k),
            "scaling": lambda **k: W.scaling(a * a, [s], **k),
            "shear": lambda **k: W.shear(a * a, shear, **k),
            "translation": lambda **k: W.translation(a * a, [one, s], **k),
            "affine_map_to": lambda **k: W.affine_map_to(
                W, a * a, [[one, fam.sc(0)], [fam.sc(0), one]], [one, s], **k),
        }
        for name, call in calls.items():
            with self.subTest(op=name):
                baseline = call()  # unbudgeted succeeds
                self.assertEqual(call(max_terms=10 ** 6, max_steps=10 ** 9), baseline)
                with self.assertRaises(ValueError) as ctx:
                    call(max_steps=0)
                self.assertIn("budget", str(ctx.exception))

    def test_budget_arguments_are_validated(self):
        fam = self.fam
        W = fam.Alg(1)
        x = W.x(0)
        with self.assertRaises(OverflowError):
            W.mul(x, x, max_terms=-1)
        with self.assertRaises(OverflowError):
            W.mul(x, x, max_steps=2 ** 128)
        with self.assertRaises(ValueError):
            W.mul(x, x, max_terms=0)
        self.assertEqual(W.mul(x, x, max_steps=2 ** 128 - 1), x * x)
        # A zero factor needs no work at all.
        self.assertTrue(W.mul(W.zero(), x, max_steps=0).is_zero())

    def test_exponents_are_checked_u128_values(self):
        fam = self.fam
        W = fam.Alg(1)
        x = W.x(0)
        big = W.monomial([2 ** 127, 0], fam.sc(1))
        self.assertEqual(big.terms(), [([2 ** 127, 0], fam.sc(1))])
        self.assertEqual(W.pow(x, 2 ** 127), big)
        with self.assertRaises(OverflowError):
            W.monomial([2 ** 128, 0], fam.sc(1))
        with self.assertRaises(ValueError):
            big * big  # the PBW exponent 2**128 does not fit in u128
        top = W.monomial([2 ** 127 - 1, 0], fam.sc(1))
        self.assertEqual((top * top).terms(), [([2 ** 128 - 2, 0], fam.sc(1))])
        with self.assertRaises(OverflowError):
            W.pow(x, 2 ** 128)

    # -- monomorphism ---------------------------------------------------

    def test_elements_of_different_contexts_raise_value_error(self):
        fam = self.fam
        W1, W2 = fam.Alg(1), fam.Alg(2)
        a, b = W1.x(0), W2.x(0)
        for op in (lambda: a + b, lambda: a - b, lambda: a * b, lambda: W1.mul(b, a),
                   lambda: W1.commutator(a, b), lambda: a.mul(b)):
            with self.assertRaises(ValueError):
                op()
        self.assertNotEqual(a, b)
        with self.assertRaises(ValueError):
            W1.fourier(b)
        with self.assertRaises(ValueError):
            W1.bernstein_degree(b)

    def test_elements_of_other_backends_raise_type_error(self):
        fam = self.fam
        W = fam.Alg(1)
        for other in FAMILIES:
            if other is fam:
                continue
            o = other.Alg(1).x(0)
            with self.subTest(other=other.name):
                for op in (lambda: W.x(0) + o, lambda: W.x(0) * o, lambda: W.x(0) - o,
                           lambda: W.mul(W.x(0), o), lambda: W.commutator(W.x(0), o)):
                    with self.assertRaises(TypeError):
                        op()
                self.assertFalse(W.x(0) == o)
                self.assertTrue(W.x(0) != o)
                with self.assertRaises(TypeError):
                    W.scalar(other.sc(1))

    def test_python_integers_are_not_weyl_elements(self):
        W = self.fam.Alg(1)
        x = W.x(0)
        for op in (lambda: x + 1, lambda: 1 + x, lambda: x * 2, lambda: 2 * x, lambda: x - 1):
            with self.assertRaises(TypeError):
                op()
        with self.assertRaises(TypeError):
            x ** -1
        with self.assertRaises(TypeError):
            x ** x
        self.assertFalse(x.is_zero())
        self.assertTrue(W.zero().is_zero())

    def test_input_validation(self):
        fam = self.fam
        W = fam.Alg(1)
        for bad in (lambda: W.x(1), lambda: W.d(1), lambda: W.generator(2),
                    lambda: W.monomial([1], fam.sc(1)),
                    lambda: W.monomial([1, 1, 1], fam.sc(1)),
                    lambda: W.translation(W.x(0), [fam.sc(1)]),
                    lambda: W.scaling(W.x(0), [fam.sc(1), fam.sc(1)]),
                    lambda: W.shear(W.x(0), [[fam.sc(1), fam.sc(1)]]),
                    lambda: fam.Alg.from_commutator([[fam.sc(1), fam.sc(0)], [fam.sc(0), fam.sc(0)]]),
                    lambda: fam.Alg.from_commutator([[fam.sc(0), fam.sc(1)]])):
            with self.assertRaises(ValueError):
                bad()
        with self.assertRaises(OverflowError):
            fam.Alg(-1)
        with self.assertRaises(TypeError):
            W.scalar(1.5)
        with self.assertRaises(ValueError):
            W.scaling(W.x(0), [fam.sc(0)])  # 0 is not a unit

    def test_elements_are_unhashable_value_objects(self):
        W = self.fam.Alg(1)
        with self.assertRaises(TypeError):
            hash(W.x(0))
        self.assertEqual(W.x(0).dim(), 2)
        self.assertEqual(W.x(0).algebra().standard_pairs(), 1)

    # -- sparse polynomials ---------------------------------------------

    def test_sparse_polynomial_ring(self):
        fam = self.fam
        P = fam.Poly
        zero, one = P(2), P.scalar(2, fam.sc(1))
        self.assertTrue(zero.is_zero())
        self.assertEqual(repr(zero), repr(fam.sc(0)))
        t0, t1 = P.variable(2, 0), P.variable(2, 1)
        self.assertEqual((t0.dim(), t0.term_count(), t0.total_degree()), (2, 1, 1))
        self.assertIsNone(zero.total_degree())
        self.assertEqual(repr(t0 * t1), "t0⋅t1")
        self.assertEqual(repr(t0 + t1), "t1 + t0")
        rng = random.Random(1300 + fam.char)
        polys = [P.monomial([rng.randrange(3), rng.randrange(3)], fam.rand(rng))
                 + P.monomial([rng.randrange(3), rng.randrange(3)], fam.rand(rng))
                 for _ in range(4)] + [zero, one, t0, t1]
        for a in polys:
            self.assertEqual(a + zero, a)
            self.assertEqual(a - a, zero)
            self.assertEqual(a * one, a)
        for a, b in itertools.product(polys, repeat=2):
            self.assertEqual(a * b, b * a)  # commutative
            self.assertEqual(a.mul(b), a * b)
        for a, b, c in itertools.product(polys, repeat=3):
            self.assertEqual((a * b) * c, a * (b * c))
            self.assertEqual(a * (b + c), a * b + a * c)
            # partial_derivative is a derivation
            self.assertEqual((a * b).partial_derivative(0),
                             a.partial_derivative(0) * b + a * b.partial_derivative(0))

    def test_sparse_polynomial_boundaries(self):
        fam = self.fam
        P = fam.Poly
        t0 = P.variable(2, 0)
        with self.assertRaises(ValueError):
            P.variable(2, 2)
        with self.assertRaises(ValueError):
            t0 + P.variable(3, 0)  # dimension mismatch
        with self.assertRaises(ValueError):
            t0 * P.variable(3, 0)
        with self.assertRaises(ValueError):
            t0.partial_derivative(5)
        with self.assertRaises(ValueError):
            (t0 + P.variable(2, 1)).mul(t0 + P.variable(2, 1), max_steps=1)
        wide = t0 + P.variable(2, 1) + P.scalar(2, fam.sc(1))
        with self.assertRaises(ValueError):
            wide.mul(wide, max_terms=2)  # the square has at least three terms everywhere
        self.assertEqual(t0.scale(fam.sc(2)), P.monomial([1, 0], fam.sc(2)))
        # A foreign backend's polynomial neither adds nor compares equal.
        other = NIMBER if fam is not NIMBER else FP3
        with self.assertRaises(TypeError):
            t0 + other.Poly.variable(2, 0)
        self.assertFalse(t0 == other.Poly.variable(2, 0))
        with self.assertRaises(TypeError):
            hash(t0)

    # -- general alternating presentations ------------------------------

    def general_form(self):
        """A 3-generator alternating form with Darboux rank (1, 1)."""
        fam = self.fam
        one = fam.sc(1)
        two = fam.sc(2)
        # A[i][j] = -A[j][i]; written so that the same data is valid everywhere.
        rows = [[fam.sc(0), one, one],
                [-one, fam.sc(0), two],
                [-one, -two, fam.sc(0)]]
        return fam.Alg.from_commutator(rows), rows

    def test_general_presentation_commutators_and_darboux_data(self):
        fam = self.fam
        G, rows = self.general_form()
        self.assertEqual((G.dim(), G.standard_pairs()), (3, None))
        self.assertEqual(G.commutator_form(), rows)
        self.assertEqual(G.darboux_ranks(), (1, 1))
        gens = [G.generator(i) for i in range(3)]
        for i, j in itertools.product(range(3), repeat=2):
            self.assertEqual(G.commutator(gens[i], gens[j]), G.scalar(rows[i][j]))
        radical = G.radical_generators()
        self.assertEqual(len(radical), 1)
        self.assertTrue(G.is_central(radical[0]))
        for g in gens:
            self.assertTrue(G.commutator(g, radical[0]).is_zero())
        self.assertFalse(G.is_central(gens[0]))
        self.assertEqual(repr(G), f"{fam.Alg.__name__}(dim=3)")

    def test_darboux_normal_form_round_trips(self):
        fam = self.fam
        G, _ = self.general_form()
        rng = random.Random(1400 + fam.char)
        for _ in range(6):
            e = rand_element(G, fam, rng, terms=3, max_exp=2)
            normal_algebra, normal = G.darboux_to_normal(e)
            self.assertEqual(normal_algebra.dim(), 3)
            self.assertEqual(normal_algebra.darboux_ranks(), (1, 1))
            self.assertEqual(G.darboux_from_normal(normal), e)
        a, b = G.generator(0) + G.generator(2), G.generator(1)
        n_alg, na = G.darboux_to_normal(a)
        _, nb = G.darboux_to_normal(b)
        _, nab = G.darboux_to_normal(a * b)
        self.assertEqual(na * nb, nab)  # the transport is multiplicative
        # The normal presentation is the Darboux block plus a zero block.
        form = n_alg.commutator_form()
        zero = fam.sc(0)
        self.assertEqual([form[i][2] for i in range(3)], [zero, zero, zero])
        self.assertEqual([form[2][j] for j in range(3)], [zero, zero, zero])
        with self.assertRaises(ValueError):
            fam.Alg(1).darboux_from_normal(G.generator(0))  # not from this normal context

    def test_standard_only_operations_refuse_general_presentations(self):
        G, _ = self.general_form()
        g = G.generator(0)
        with self.assertRaises(ValueError):
            G.fourier(g)
        with self.assertRaises(ValueError):
            G.x(0)

    def test_pure_radical_presentation(self):
        fam = self.fam
        zero = fam.sc(0)
        Z = fam.Alg.from_commutator([[zero, zero], [zero, zero]])
        self.assertEqual(Z.darboux_ranks(), (0, 2))
        a, b = Z.generator(0), Z.generator(1)
        self.assertEqual(a * b, b * a)
        self.assertEqual(len(Z.radical_generators()), 2)
        self.assertTrue(Z.is_central(a))


# ---------------------------------------------------------------------------
# Positive characteristic: centre, fibres, p-symbols, modules
# ---------------------------------------------------------------------------


class CharPWeylLaws:
    """Mixin for the backends of characteristic p > 0 (Fp3, Nimber)."""

    fam = None

    @property
    def p(self):
        return self.fam.char

    def central_values(self, n=1):
        """Distinct, non-trivial values chi(z_i^p)."""
        fam = self.fam
        raw = [2, 1, 3, 2] if fam.char == 2 else [2, 1, 2, 1]
        return [fam.sc(v) for v in raw[:2 * n]]

    def test_centre_is_generated_by_p_th_powers(self):
        fam, p = self.fam, self.p
        for n in (1, 2):
            W = fam.Alg(n)
            gens = W.center_generators()
            self.assertEqual(len(gens), 2 * n)
            self.assertEqual(gens, [W.generator(i) ** p for i in range(2 * n)])
            for g in gens:
                self.assertTrue(W.is_central(g))
            self.assertEqual(W.center_rank_over_center(), p ** (2 * n))
        W = fam.Alg(1)
        self.assertFalse(W.is_central(W.x(0)))
        self.assertFalse(W.is_central(W.x(0) * W.d(0)))
        for k in range(1, p):
            self.assertFalse(W.is_central(W.x(0) ** k))

    def test_centre_basis_enumerates_pbw_monomials_in_base_p(self):
        fam, p = self.fam, self.p
        for n in (1, 2):
            W = fam.Alg(n)
            rank = p ** (2 * n)
            for index in range(rank):
                digits, rest = [], index
                for _ in range(2 * n):
                    digits.append(rest % p)
                    rest //= p
                expected = W.monomial(digits, fam.sc(1))
                self.assertEqual(W.center_basis_element(index), expected, index)
        W = fam.Alg(1)
        with self.assertRaises(ValueError):
            W.center_basis_element(p ** 2)  # outside the rank
        with self.assertRaises(OverflowError):
            W.center_basis_element(2 ** 200)

    def test_centre_rank_is_p_to_the_2n(self):
        fam, p = self.fam, self.p
        for n in (0, 1, 2, 3, 12):
            self.assertEqual(fam.Alg(n).center_rank_over_center(), p ** (2 * n))

    def test_central_elements_are_exactly_those_commuting_with_every_generator(self):
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        rng = random.Random(2000 + p)
        for _ in range(10):
            e = rand_element(W, fam, rng, 3, max_exp=2 * p)
            central = W.is_central(e)
            commutes = all(W.commutator(e, g).is_zero() for g in (x, d))
            self.assertEqual(central, commutes)
        # Polynomials in x^p and d^p are central.
        e = (x ** p).scale(fam.sc(2)) * (d ** p) + (d ** p) + W.scalar(fam.sc(1))
        self.assertTrue(W.is_central(e))

    def test_central_reduction_substitutes_the_central_character(self):
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        a, b = self.central_values()
        x, d = W.x(0), W.d(0)
        dim = p ** 2
        for k in range(3 * p):
            expected_x = x.scale(a ** (k // p)) if k % p else W.scalar(a ** (k // p))
            if k % p == 0:
                expected_x = W.scalar(a ** (k // p))
            else:
                expected_x = (x ** (k % p)).scale(a ** (k // p))
            self.assertEqual(W.central_reduce(x ** k, [a, b], dim), expected_x, k)
            expected_d = (d ** (k % p)).scale(b ** (k // p))
            self.assertEqual(W.central_reduce(d ** k, [a, b], dim), expected_d, k)
        # z_i^p reduces to the character value itself.
        self.assertEqual(W.central_reduce(x ** p, [a, b], dim), W.scalar(a))
        self.assertEqual(W.central_reduce(d ** p, [a, b], dim), W.scalar(b))

    def test_central_reduction_is_a_ring_homomorphism_onto_the_fibre(self):
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        values = self.central_values()
        dim = p ** 2
        rng = random.Random(2100 + p)
        for _ in range(8):
            u = rand_element(W, fam, rng, 3, max_exp=2 * p)
            v = rand_element(W, fam, rng, 3, max_exp=2 * p)
            ru, rv = (W.central_reduce(e, values, dim) for e in (u, v))
            self.assertEqual(W.central_reduce(u + v, values, dim), ru + rv)
            self.assertEqual(W.central_reduce(u * v, values, dim),
                             W.central_reduce(ru * rv, values, dim))
            self.assertEqual(W.central_reduce(ru, values, dim), ru)  # idempotent
            # reduced representatives have all exponents below p
            for exps, _ in ru.terms():
                self.assertTrue(all(e < p for e in exps))

    def test_central_reduction_validates_its_inputs(self):
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        values = self.central_values()
        with self.assertRaises(ValueError):
            W.central_reduce(W.x(0), values[:1], p ** 2)  # one value per generator
        with self.assertRaises(ValueError):
            W.central_reduce(W.x(0), values, p ** 2 - 1)  # basis dimension too small
        with self.assertRaises(ValueError):
            W.central_reduce(fam.Alg(2).x(0), values, p ** 2)  # foreign context

    def test_psymbol_data(self):
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        a, b = self.central_values()
        P = W.psymbol([a, b], p ** 2)
        self.assertEqual((P.characteristic(), P.tensor_rank()), (p, 1))
        self.assertEqual(P.pairs(), [(a, b)])
        self.assertIsNone(P.brauer_split())  # no certificate attached yet
        self.assertEqual(repr(P), f"{fam.PSym.__name__}(characteristic={p}, tensor_rank=1)")
        W2 = fam.Alg(2)
        vals = self.central_values(2)
        P2 = W2.psymbol(vals, p ** 4)
        self.assertEqual(P2.tensor_rank(), 2)
        # values are listed in generator order: x_0^p, x_1^p, d_0^p, d_1^p
        self.assertEqual(P2.pairs(), [(vals[0], vals[2]), (vals[1], vals[3])])

    def test_cyclic_factors_of_every_pair(self):
        fam, p = self.fam, self.p
        W = fam.Alg(2)
        vals = self.central_values(2)  # x0^p, x1^p, d0^p, d1^p
        P = W.psymbol(vals, p ** 4)
        for pair in range(2):
            a, b = vals[pair], vals[2 + pair]
            self.assertEqual(P.cyclic_factor(pair, p ** 4), (b, a * b))

    def test_cyclic_factor_parameters(self):
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        a, b = self.central_values()
        P = W.psymbol([a, b], p ** 2)
        got_b, got_c = P.cyclic_factor(0, p ** 2)
        self.assertEqual(got_b, b)  # b = d^p
        self.assertEqual(got_c, a * b)  # c = x^p d^p
        self.assertEqual(P.cyclic_factor(0, p ** 2, max_terms=64, max_steps=10 ** 5), (b, a * b))
        with self.assertRaises(ValueError):
            P.cyclic_factor(1, p ** 2)  # no second pair

    def test_p_residue_is_the_top_coefficient_and_vanishes_on_commutators(self):
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        a, b = self.central_values()
        P = W.psymbol([a, b], p ** 2)
        zero = fam.sc(0)
        top = p - 1
        self.assertEqual(P.p_residue(W.monomial([top, top], fam.sc(1))), fam.sc(1))
        # x^(top + p k) d^(top + p l) reduces to a^k b^l x^top d^top.
        for k, l in itertools.product(range(3), repeat=2):
            element = W.monomial([top + p * k, top + p * l], fam.sc(1))
            self.assertEqual(P.p_residue(element), (a ** k) * (b ** l), (k, l))
        for exps in itertools.product(range(p), repeat=2):
            if exps != (top, top):
                self.assertEqual(P.p_residue(W.monomial(list(exps), fam.sc(1))), zero)
        rng = random.Random(2200 + p)
        for _ in range(12):
            u = rand_element(W, fam, rng, 3, max_exp=2 * p)
            v = rand_element(W, fam, rng, 3, max_exp=2 * p)
            self.assertEqual(P.p_residue(u + v), P.p_residue(u) + P.p_residue(v))
            self.assertEqual(P.p_residue(W.commutator(u, v)), zero)
        with self.assertRaises(ValueError):
            P.p_residue(fam.Alg(2).x(0))

    def test_generator_matrices_form_a_representation_of_the_fibre(self):
        fam, p = self.fam, self.p
        a, b = self.central_values()
        W = fam.Alg(1)
        roots = self.splitting_roots([a, b])
        mats = W.central_character_generator_matrices([a, b], roots, p ** 2, 100, 10 ** 6)
        mx, md = mats
        n = p
        self.assertEqual((len(mx), len(mx[0])), (n, n))
        one = identity(fam, n)
        # [d, x] = 1 on the module, x^p = a, d^p = b.
        self.assertEqual(matsub(matmul(fam, md, mx), matmul(fam, mx, md)), one)
        self.assertEqual(matpow(fam, mx, p), scalar_matrix(fam, n, a))
        self.assertEqual(matpow(fam, md, p), scalar_matrix(fam, n, b))

    def splitting_roots(self, values):
        """Roots r_i with r_i^p = chi_i."""
        fam = self.fam
        roots = []
        for v in values:
            if fam.char == 2:
                roots.append(v.sqrt())
            else:
                roots.append(next(r for r in (fam.sc(i) for i in range(self.p)) if r ** 3 == v))
        return roots

    def test_generator_matrices_in_rank_two_respect_the_tensor_structure(self):
        fam, p = self.fam, self.p
        W = fam.Alg(2)
        values = self.central_values(2)
        roots = self.splitting_roots(values)
        size = p ** 2
        mats = W.central_character_generator_matrices(values, roots, p ** 4, 10 ** 4, 10 ** 7)
        x0, x1, d0, d1 = mats
        self.assertEqual(len(x0), size)
        one, zero = identity(fam, size), scalar_matrix(fam, size, fam.sc(0))

        def comm(u, v):
            return matsub(matmul(fam, u, v), matmul(fam, v, u))

        self.assertEqual(comm(d0, x0), one)
        self.assertEqual(comm(d1, x1), one)
        for u, v in ((d0, x1), (d1, x0), (x0, x1), (d0, d1)):
            self.assertEqual(comm(u, v), zero)
        for matrix, value in zip((x0, x1, d0, d1), values):
            self.assertEqual(matpow(fam, matrix, p), scalar_matrix(fam, size, value))

    def evaluate_on_module(self, element, mats):
        """The matrix of a PBW element on the split module (independent of the
        binding's product): sum of coeff * M_0^e_0 * M_1^e_1 * ... in PBW order."""
        fam = self.fam
        size = len(mats[0])
        total = scalar_matrix(fam, size, fam.sc(0))
        for exps, coeff in element.terms():
            term = scalar_matrix(fam, size, coeff)
            for matrix, e in zip(mats, exps):
                term = matmul(fam, term, matpow(fam, matrix, e))
            total = matadd(total, term)
        return total

    def test_pbw_products_agree_with_matrix_multiplication_on_the_split_module(self):
        # The split module is a genuine representation, so the binding's PBW
        # multiplication must agree with matrix multiplication in Python.
        fam, p = self.fam, self.p
        for n, max_exp, rounds in ((1, 2 * p, 6), (2, 3, 2)):
            W = fam.Alg(n)
            values = self.central_values(n)
            roots = self.splitting_roots(values)
            mats = W.central_character_generator_matrices(
                values, roots, p ** (2 * n), 10 ** 4, 10 ** 8)
            rng = random.Random(5000 + 10 * p + n)
            for _ in range(rounds):
                a = rand_element(W, fam, rng, 3, max_exp=max_exp)
                b = rand_element(W, fam, rng, 3, max_exp=max_exp)
                with self.subTest(rank=n):
                    self.assertEqual(self.evaluate_on_module(a * b, mats),
                                     matmul(fam, self.evaluate_on_module(a, mats),
                                            self.evaluate_on_module(b, mats)))
                    self.assertEqual(self.evaluate_on_module(a + b, mats),
                                     matadd(self.evaluate_on_module(a, mats),
                                            self.evaluate_on_module(b, mats)))

    def test_wrong_roots_and_small_budgets_are_refused(self):
        fam, p = self.fam, self.p
        a, b = self.central_values()
        W = fam.Alg(1)
        roots = self.splitting_roots([a, b])
        wrong = [fam.sc(1), fam.sc(1)] if a != fam.sc(1) else [fam.sc(2), fam.sc(2)]
        with self.assertRaises(ValueError):
            W.central_character_generator_matrices([a, b], wrong, p ** 2, 100, 10 ** 6)
        with self.assertRaises(ValueError):
            W.central_character_generator_matrices([a, b], roots, p ** 2, 1, 10 ** 6)  # matrix entries
        with self.assertRaises(ValueError):
            W.central_character_generator_matrices([a, b], roots, p ** 2, 100, 1)  # work budget

    def test_split_trace_matches_the_residue_on_every_reduced_monomial(self):
        fam, p = self.fam, self.p
        a, b = self.central_values()
        W = fam.Alg(1)
        P = W.psymbol([a, b], p ** 2)
        roots = self.splitting_roots([a, b])
        for exps in itertools.product(range(p), repeat=2):
            element = W.monomial(list(exps), fam.sc(1))
            self.assertTrue(P.split_trace_matches_residue(element, roots, p ** 2, 100, 10 ** 6),
                            exps)
        rng = random.Random(2300 + p)
        for _ in range(5):
            e = rand_element(W, fam, rng, 3, max_exp=2 * p)
            self.assertTrue(P.split_trace_matches_residue(e, roots, p ** 2, 100, 10 ** 6))

    def test_central_character_pullbacks_agree_with_the_automorphisms(self):
        # The pullback of chi along phi has values chi(phi(z_i^p)); compute that
        # independently by applying phi to z_i^p and central-reducing.
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        values = self.central_values()
        dim = p ** 2
        s = fam.sc(2)
        a = fam.sc(1)
        t = [fam.sc(1), fam.sc(2)]
        cases = [
            ("fourier", W.fourier_central_character(values, dim), W.fourier),
            ("scaling", W.scaling_central_character(values, [s], dim), lambda e: W.scaling(e, [s])),
            ("shear", W.shear_central_character(values, [[a]], dim), lambda e: W.shear(e, [[a]])),
            ("translation", W.translation_central_character(values, t, dim),
             lambda e: W.translation(e, t)),
        ]
        for name, pulled, phi in cases:
            with self.subTest(map=name):
                self.assertEqual(len(pulled), 2)
                for i in range(2):
                    image = phi(W.generator(i) ** p)
                    self.assertEqual(W.central_reduce(image, values, dim), W.scalar(pulled[i]))

    def test_translation_shifts_the_character_by_the_p_th_power(self):
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        values = self.central_values()
        t = [fam.sc(1), fam.sc(2)]
        pulled = W.translation_central_character(values, t, p ** 2)
        self.assertEqual(pulled, [values[0] + t[0] ** p, values[1] + t[1] ** p])
        scaled = W.scaling_central_character(values, [fam.sc(2)], p ** 2)
        s = fam.sc(2)
        self.assertEqual(scaled, [values[0] * s ** p, values[1] * s.inv() ** p])

    def test_fibre_budgets_exist_on_every_fibre_operation(self):
        fam, p = self.fam, self.p
        W = fam.Alg(1)
        values = self.central_values()
        with self.assertRaises(ValueError):
            W.psymbol(values, p ** 2 - 1)
        with self.assertRaises(ValueError):
            W.fourier_central_character(values, 1)
        with self.assertRaises(ValueError):
            W.center_generators(max_steps=0)
        with self.assertRaises(ValueError):
            W.center_basis_element(1, max_steps=0)
        with self.assertRaises(ValueError):
            W.psymbol(values, p ** 2).cyclic_factor(0, p ** 2, max_steps=0)

    def test_transported_fibre_of_a_general_presentation(self):
        fam, p = self.fam, self.p
        # Presentation with a radical direction; the fibre has paired values
        # (one per Darboux pair) and a radical value.
        zero, one, two = fam.sc(0), fam.sc(1), fam.sc(2)
        rows = [[zero, one, one], [-one, zero, two], [-one, -two, zero]]
        G = fam.Alg.from_commutator(rows)
        paired = self.central_values()
        radical_values = [fam.sc(1)]
        dim = p ** 3
        g0, g1, g2 = (G.generator(i) for i in range(3))
        self.assertTrue(G.transported_fiber_products_agree(g0, g1, paired, radical_values, dim))
        rng = random.Random(2400 + p)
        for _ in range(4):
            u = rand_element(G, fam, rng, 2, max_exp=p)
            v = rand_element(G, fam, rng, 2, max_exp=p)
            self.assertTrue(G.transported_fiber_products_agree(
                u, v, paired, radical_values, dim, max_terms=4096, max_steps=10 ** 6))
            ru = G.transported_central_reduce(u, paired, radical_values, dim)
            # the canonical lift is stable under a second reduction
            self.assertEqual(G.transported_central_reduce(ru, paired, radical_values, dim), ru)
        with self.assertRaises(ValueError):
            G.psymbol(paired, dim)  # p-symbols need a standard presentation
        self.assertEqual(len(G.center_generators()), 3)
        # Rank over the centre counts only the Darboux (Weyl) part.
        self.assertEqual(G.center_rank_over_center(), p ** 2)


