class RationalWeylTests(WeylFamilyLaws, OgdoadTestCase):
    fam = RATIONAL

    def test_signs_are_real_in_characteristic_zero(self):
        W = RATIONAL.Alg(1)
        self.assertEqual(repr(W.commutator(W.x(0), W.d(0))), "-1")
        self.assertEqual(W.commutator_form(), [[0, -1], [1, 0]])
        self.assertEqual(repr(W.fourier(W.d(0))), "-z0")
        self.assertEqual(W.parity(W.x(0)), -W.x(0))

    def test_centre_is_trivial_and_positive_characteristic_tools_refuse(self):
        fam = RATIONAL
        W = fam.Alg(1)
        x, d = W.x(0), W.d(0)
        one = fam.sc(1)
        self.assertTrue(W.is_central(W.scalar(fam.sc(5))))
        for e in (x, d, x * d, x ** 2 * d, x + W.one()):
            self.assertFalse(W.is_central(e))
        refusals = [
            lambda: W.center_generators(),
            lambda: W.center_rank_over_center(),
            lambda: W.center_basis_element(0),
            lambda: W.psymbol([one, one], 4),
            lambda: W.central_reduce(x, [one, one], 4),
            lambda: W.fourier_central_character([one, one], 4),
            lambda: W.clifford_fiber_products_agree(x, d, [one, one], 4),
            lambda: W.central_character_generator_matrices([one, one], [one, one], 4, 100, 100),
        ]
        for refusal in refusals:
            with self.assertRaises(ValueError):
                refusal()

    def test_exact_rational_coefficients(self):
        W = RATIONAL.Alg(1)
        x = W.x(0)
        half = og.Rational(1, 2)
        self.assertEqual(repr((x * W.d(0)).scale(half)), "(1/2)⋅z0⋅z1")
        self.assertEqual(W.scaling(W.d(0), [og.Rational(2)]), W.d(0).scale(half))
        self.assertEqual(W.scalar((1, 3)).terms(), [([0, 0], og.Rational(1, 3))])

    def test_action_on_polynomials_has_integer_derivatives(self):
        W = RATIONAL.Alg(1)
        t4 = og.RationalSparsePolynomial.monomial([4], og.Rational(1))
        self.assertEqual(repr(W.act_on_sparse_polynomial(W.d(0), t4)), "4⋅t0↑3")


class Fp3WeylTests(CharPWeylLaws, WeylFamilyLaws, OgdoadTestCase):
    fam = FP3

    def test_odd_characteristic_signs(self):
        W = FP3.Alg(1)
        s = FP3.sc
        self.assertEqual(W.commutator_form(), [[s(0), s(2)], [s(1), s(0)]])
        self.assertEqual(repr(W.fourier(W.d(0))), "-z0")
        self.assertEqual(repr(W.parity(W.x(0))), "-z0")
        self.assertEqual(repr(W.center_generators()), "[z0↑3, z1↑3]")

    def test_readme_split_and_trace_certificates(self):
        W3 = og.Fp3WeylAlgebra(1)
        P3 = W3.psymbol([og.Fp3(2), og.Fp3(1)], 9)
        self.assertTrue(P3.certify_split([og.Fp3(2), og.Fp3(1)], 9, 100, 1_000_000))
        self.assertTrue(P3.split_trace_matches_residue(
            W3.monomial([2, 2], 1), [og.Fp3(2), og.Fp3(1)], 9, 100, 1_000_000))

    def test_split_certificate_needs_true_roots_and_budget(self):
        W = FP3.Alg(1)
        a, b = FP3.sc(2), FP3.sc(1)
        P = W.psymbol([a, b], 9)
        roots = [FP3.sc(2), FP3.sc(1)]  # 2^3 = 2 and 1^3 = 1 in F_3
        self.assertTrue(P.certify_split(roots, 9, 100, 10 ** 6))
        self.assertEqual(P.brauer_split(), None)  # the report is attached only by certify_split
        with self.assertRaises(ValueError):
            P.certify_split([FP3.sc(1), FP3.sc(1)], 9, 100, 10 ** 6)  # 1^3 != 2
        with self.assertRaises(ValueError):
            P.certify_split(roots, 9, 5, 10 ** 6)  # matrix storage budget
        with self.assertRaises(ValueError):
            P.certify_split(roots, 9, 100, 1)  # evaluation budget

    def test_clifford_bridge_is_a_characteristic_two_tool(self):
        W = FP3.Alg(1)
        one = FP3.sc(1)
        with self.assertRaises(ValueError):
            W.clifford_fiber_products_agree(W.d(0) * W.x(0), W.x(0), [one, one], 9)

    def test_central_character_generator_matrices_have_the_demo_shape(self):
        W = FP3.Alg(1)
        mx, md = W.central_character_generator_matrices(
            [FP3.sc(2), FP3.sc(1)], [FP3.sc(2), FP3.sc(1)], 9, 100, 10 ** 6)
        s = FP3.sc
        self.assertEqual(mx, [[s(2), s(0), s(0)], [s(1), s(2), s(0)], [s(0), s(1), s(2)]])
        self.assertEqual(md, [[s(1), s(1), s(0)], [s(0), s(1), s(2)], [s(0), s(0), s(1)]])

    def test_centre_rank_reports_none_past_u128(self):
        # 3^80 < 2^128 < 3^82: the rank is exact for 40 pairs and unrepresentable
        # for 41 (the dev build is slow here, so only this backend is probed).
        self.assertEqual(FP3.Alg(40).center_rank_over_center(), 3 ** 80)
        self.assertIsNone(FP3.Alg(41).center_rank_over_center())

    def test_rank_two_fibre_has_81_dimensions(self):
        W = FP3.Alg(2)
        self.assertEqual(W.center_rank_over_center(), 81)
        P = W.psymbol([FP3.sc(1)] * 4, 81)
        self.assertEqual(P.tensor_rank(), 2)
        self.assertEqual(P.pairs(), [(FP3.sc(1), FP3.sc(1))] * 2)
        with self.assertRaises(ValueError):
            W.psymbol([FP3.sc(1)] * 4, 80)


class NimberWeylTests(CharPWeylLaws, WeylFamilyLaws, OgdoadTestCase):
    fam = NIMBER

    def test_negation_is_trivial_in_characteristic_two(self):
        W = NIMBER.Alg(1)
        x, d = W.x(0), W.d(0)
        self.assertEqual(-x, x)
        self.assertEqual(W.commutator(x, d), W.commutator(d, x))
        self.assertEqual(W.fourier(d), x)
        self.assertEqual(W.parity(x), x)
        self.assertEqual(W.parity(x * d + d), x * d + d)
        self.assertEqual(W.commutator_form(), [[og.Nimber(0), og.Nimber(1)], [og.Nimber(1), og.Nimber(0)]])
        self.assertEqual(repr(W.center_generators()), "[z0↑2, z1↑2]")

    def test_demo_centre_and_fibre(self):
        W = og.NimberWeylAlgebra(1)
        x, d = W.x(0), W.d(0)
        self.assertEqual(W.commutator(d, x), W.one())
        self.assertEqual(W.center_rank_over_center(), 4)
        self.assertEqual(W.center_basis_element(3), x * d)
        values = [og.Nimber(2), og.Nimber(3)]
        self.assertEqual(W.central_reduce(x ** 3, values, 4), x.scale(og.Nimber(2)))
        self.assertTrue(W.clifford_fiber_products_agree(
            d * x, x + d, values, 4, max_terms=32, max_steps=1_000))

    def test_demo_symbols_psymbol_and_shear(self):
        W = og.NimberWeylAlgebra(1)
        x, d = W.x(0), W.d(0)
        values = [og.Nimber(2), og.Nimber(3)]
        t2 = og.NimberSparsePolynomial.monomial([2], 1)
        self.assertEqual(W.act_on_sparse_polynomial(d, t2),
                         og.NimberSparsePolynomial.monomial([1], 0))  # d(t^2) = 0
        poly = t2 + og.NimberSparsePolynomial.monomial([1], 1)
        self.assertEqual(W.act_on_sparse_polynomial(d, poly), og.NimberSparsePolynomial.scalar(1, 1))
        self.assertEqual(W.principal_symbol(d * x, "bernstein"),
                         og.NimberSparsePolynomial.monomial([1, 1], 1))
        self.assertEqual(W.poisson_bracket(og.NimberSparsePolynomial.variable(2, 1),
                                           og.NimberSparsePolynomial.variable(2, 0)),
                         og.NimberSparsePolynomial.scalar(2, 1))
        self.assertEqual(W.fourier_inverse(W.fourier(x + d)), x + d)
        P = W.psymbol(values, 4)
        self.assertTrue(P.tensor_rank() == 1 and P.brauer_split() is None)
        self.assertEqual(P.p_residue(x * d), og.Nimber(1))
        b, c = P.cyclic_factor(0, 4, max_terms=32, max_steps=1_000)
        self.assertEqual((b, c), (og.Nimber(3), og.Nimber(2) * og.Nimber(3)))
        self.assertEqual(P.cyclic_factor(0, 4), (og.Nimber(3), og.Nimber(1)))  # README
        # The quadratic correction of the shear is retained in characteristic two.
        self.assertEqual(
            W.shear_central_character(values, [[og.Nimber(1)]], 4), [og.Nimber(2), og.Nimber(0)])

    def test_odd_characteristic_certificates_refuse_characteristic_two(self):
        W = NIMBER.Alg(1)
        P = W.psymbol([og.Nimber(2), og.Nimber(3)], 4)
        roots = [og.Nimber(2).sqrt(), og.Nimber(3).sqrt()]
        with self.assertRaises(ValueError):
            P.certify_split(roots, 4, 100, 10 ** 6)

    def test_clifford_fibre_oracle_agrees_on_random_elements(self):
        fam = NIMBER
        W = fam.Alg(1)
        values = [og.Nimber(2), og.Nimber(3)]
        rng = random.Random(3000)
        for _ in range(10):
            u = rand_element(W, fam, rng, 3, max_exp=4)
            v = rand_element(W, fam, rng, 3, max_exp=4)
            self.assertTrue(W.clifford_fiber_products_agree(u, v, values, 4,
                                                            max_terms=4096, max_steps=10 ** 6))
        W2 = fam.Alg(2)
        vals2 = [og.Nimber(v) for v in (2, 1, 3, 2)]
        a = W2.x(0) * W2.d(1) + W2.d(0)
        b = W2.x(1) + W2.x(0) * W2.d(0)
        self.assertTrue(W2.clifford_fiber_products_agree(a, b, vals2, 16))

    def test_clifford_bridge_budgets(self):
        W = NIMBER.Alg(1)
        values = [og.Nimber(2), og.Nimber(3)]
        with self.assertRaises(ValueError):
            W.clifford_fiber_products_agree(W.x(0), W.d(0), values, 4, max_steps=0)
        with self.assertRaises(ValueError):
            W.clifford_fiber_products_agree(W.x(0), W.d(0), values, 3)  # basis dimension < 4

    def test_demo_general_presentation_with_transport(self):
        general = og.NimberWeylAlgebra.from_commutator([[0, 1, 1], [1, 0, 2], [1, 2, 0]])
        self.assertEqual(general.darboux_ranks(), (1, 1))
        value = general.generator(0) * general.generator(1)
        normal_algebra, normal_value = general.darboux_to_normal(value)
        self.assertEqual(normal_algebra.dim(), 3)
        self.assertEqual(general.darboux_from_normal(normal_value), value)
        self.assertTrue(general.transported_fiber_products_agree(
            general.generator(0), general.generator(1),
            [og.Nimber(2), og.Nimber(3)], [og.Nimber(1)], 4, max_terms=128, max_steps=10_000))
        self.assertEqual(repr(general.radical_generators()),
                         "[z2 + z1 + *2⋅z0]")
        self.assertEqual(general.commutator_form()[1][2], og.Nimber(2))

    def test_split_module_dimension_from_the_demo(self):
        W = og.NimberWeylAlgebra(1)
        roots = [og.Nimber(og.nim_sqrt(2)), og.Nimber(og.nim_sqrt(3))]
        gens = W.central_character_generator_matrices(
            [og.Nimber(2), og.Nimber(3)], roots,
            max_basis_dimension=2 ** 1 * 2, max_matrix_entries=8, max_steps=10_000)
        self.assertEqual(len(gens), 2)
        self.assertEqual(len(gens[0]), 2)


# ---------------------------------------------------------------------------
# Cross-backend facts
# ---------------------------------------------------------------------------


class WeylFamilyStructureTests(OgdoadTestCase):
    def test_each_family_has_four_classes_in_the_module(self):
        for fam in FAMILIES:
            for cls in (fam.Alg, fam.Elem, fam.Poly, fam.PSym):
                self.assertTrue(cls.__name__.startswith(fam.name), cls.__name__)
                self.assertIs(getattr(og, cls.__name__), cls)

    def test_algebra_remembers_its_backend_through_elements(self):
        for fam in FAMILIES:
            W = fam.Alg(1)
            x = W.x(0)
            self.assertIsInstance(x, fam.Elem)
            self.assertIsInstance(x.algebra(), fam.Alg)
            self.assertIsInstance(W.principal_symbol(x, "bernstein"), fam.Poly)

    def test_algebra_objects_compare_by_commutator_form(self):
        # Algebras compare by their commutator form, as their elements do: two
        # algebras built from the same form, or ``x.algebra()`` fetched twice,
        # are equal.
        for fam in FAMILIES:
            self.assertEqual(fam.Alg(1), fam.Alg(1), fam.name)
            W = fam.Alg(2)
            self.assertEqual(W.x(0).algebra(), W.x(0).algebra(), fam.name)

    def test_scalars_are_returned_in_the_backend_world(self):
        W = og.NimberWeylAlgebra(1)
        self.assertIsInstance(W.commutator_form()[0][0], og.Nimber)
        self.assertIsInstance(W.x(0).terms()[0][1], og.Nimber)
        W3 = og.Fp3WeylAlgebra(1)
        self.assertIsInstance(W3.x(0).terms()[0][1], og.Fp3)
        Wr = og.RationalWeylAlgebra(1)
        self.assertIsInstance(Wr.x(0).terms()[0][1], og.Rational)

    def test_backends_differ_where_the_characteristic_matters(self):
        # (x + d)^2 = x^2 + 2 x d + d^2 + 1 collapses differently per world.
        results = {}
        for fam in FAMILIES:
            W = fam.Alg(1)
            a = W.x(0) + W.d(0)
            results[fam.name] = (a * a).terms()
        self.assertEqual(len(results["Rational"]), 4)  # the 2xd term survives
        self.assertEqual(len(results["Nimber"]), 3)  # 2xd = 0 in characteristic two
        self.assertEqual(len(results["Fp3"]), 4)  # 2xd = -xd in characteristic three


if __name__ == "__main__":
    unittest.main()
